import {initWoolworths} from './woolworths.js';
import {initNewWorld} from './newworld.js';
import {foods,recipes,days,defaults,sanitise,meal,plan,sceneInventory,stockStatus,unitPrice,findFood,horizon} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],key='assembl-kitchen-v3';
const money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD',maximumFractionDigits:2}).format(n);
const cleanQty=n=>Math.round(n*10)/10;
const places={fridge:'Fridge shelf',crisper:'Crisper drawer',bench:'Fruit bowl',pantry:'Pantry',freezer:'Freezer'};
const statusNames={fresh:'Plenty of time',soon:'Use first',overdue:'Past planning date',frozen:'Frozen',used:'Logged as used',wasted:'Logged as wasted'};
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state=defaults(),scene=null,selected='spinach',filter='all',door=true,playing=null,toastTimer,previous=null,scanURL=null,ocrBusy=false;
try{const raw=localStorage.getItem(key);if(raw)state=sanitise(JSON.parse(raw));}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('#savedStatus').textContent='● Saved on this device';}catch{$('#savedStatus').textContent='Storage unavailable · session only';}}
function checkpoint(){previous=structuredClone(state);}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function update(){save();renderControls();renderInventory();renderInspector();renderMetrics();renderMeals();renderShopping();scene?.setItems(sceneInventory(state));scene?.setDay(state.day);scene?.setSelected(selected);}
function renderControls(){$('#adultsCount').textContent=state.adults;$('#kidsCount').textContent=state.kids;$$('#kidsToggle button').forEach(b=>{const active=String(state.kidsHome)===b.dataset.value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('#away').checked=state.away;$('#lunch').checked=state.lunch;$('#includePlanned').checked=state.includePlanned;$('#budget').value=state.budget;$('#budgetLabel').textContent=money(state.budget);$('#day').value=state.day;$('#dayTitle').textContent=days[state.day];$('#modeBadge').textContent=state.sample?'● Example kitchen · editable':'● Your kitchen · planning mode';for(const id of ['mainDay','topDay','diet','retailer'])$('#'+id).value=state[id];const total=plan(state).total;$('#budgetStatus').textContent=(total<=state.budget?money(state.budget-total)+' below your budget':money(total-state.budget)+' over your budget')+' in this scenario.';const urgent=sceneInventory(state).filter(x=>x.status==='soon'||x.status==='overdue').sort((a,b)=>a.due-b.due);$('#missionTitle').textContent=urgent.length?'Make a plan for '+urgent[0].name.toLowerCase()+'.':'A little breathing room.';$('#missionCopy').textContent=urgent.length?'Choose a meal, inspect the date, or make a freezer plan.':'Try changing the household or moving through the week.';$('#missionAction').dataset.target=urgent[0]?.id||state.inventory[0]?.id||'';}
function renderMetrics(){const p=plan(state);$('#basketTotal').textContent=money(p.total);$('#stockValue').textContent=money(p.avoided);$('#urgentCount').textContent=sceneInventory(state).filter(x=>['soon','overdue'].includes(x.status)).length+' items';$('#wins').textContent=state.events.filter(x=>['used','frozen'].includes(x.action)).length+' moves';}
function renderInventory(){const list=state.inventory.filter(x=>!x.action&&x.qty>0).filter(x=>filter==='all'||(filter==='soon'&&['soon','overdue'].includes(stockStatus(x,state.day)))||(filter==='fridge'&&['fridge','crisper'].includes(x.place))||(filter==='freezer'&&x.place==='freezer')||(filter==='pantry'&&['pantry','bench'].includes(x.place)));$('#inventoryCards').innerHTML=list.length?list.map(x=>{const f=foods.find(f=>f.id===x.id),status=stockStatus(x,state.day);return `<button class="food-card ${selected===x.id?'selected':''}" data-select="${f.id}"><img src="assets/${f.image}.jpg" alt="${f.name}" loading="lazy"><div class="card-content"><h3>${f.name}</h3><small>${cleanQty(x.qty)} ${f.unit} · ${places[x.place]}</small><span class="food-status ${status}">${statusNames[status]}</span></div></button>`}).join(''):'<div class="empty-state">Nothing in this view. Add what you have, or explore another part of the kitchen.</div>';}
function renderInspector(){const x=state.inventory.find(x=>x.id===selected);const projectedFood=sceneInventory(state).find(x=>x.id===selected);if(!x&&projectedFood){const f=projectedFood;$('#inspector').innerHTML=`<span class="eyebrow">PLANNED SHOP · NOT PURCHASED</span><img class="food-photo" src="assets/${f.image}.jpg" alt="${f.name}"><h3>${f.name}</h3><span class="food-status ${f.status}">${statusNames[f.status]}</span><div class="food-meta"><div><small>Projected ${days[state.day]}</small><strong>${cleanQty(f.qty)} ${f.unit}</strong></div><div><small>Belongs in</small><strong>${places[f.place]}</strong></div></div><p>This food is from your planned shopping list. It has not been bought. Turn off planned arrivals to see only your recorded kitchen.</p><button class="button plum full" data-edit="${f.id}">Record food I already have</button>`;return;}if(!x){$('#inspector').innerHTML='<span class="eyebrow">YOUR KITCHEN, UP CLOSE</span><div class="empty-icon">↖</div><h3>Pick something good.</h3><p>Tap food in the 3D kitchen, or choose an ingredient below. Add your own stock to make this personal.</p><button class="button plum full" data-open="inventoryDialog">+ Add food</button>';return;}const f=foods.find(f=>f.id===x.id),status=stockStatus(x,state.day),projected=sceneInventory(state).find(v=>v.id===x.id);const remaining=x.due-state.day;$('#inspector').innerHTML=`<span class="eyebrow">IN YOUR KITCHEN</span><img class="food-photo" src="assets/${f.image}.jpg" alt="${f.name}"><h3>${f.name}</h3><span class="food-status ${status}">${statusNames[status]}</span><div class="food-meta"><div><small>Recorded stock</small><strong>${cleanQty(x.qty)} ${f.unit}</strong></div><div><small>${x.place==='freezer'?'Stored in':'Planning window'}</small><strong>${x.place==='freezer'?'Freezer':remaining<0?Math.abs(remaining)+' days past':remaining===0?'Today':remaining+' day'+(remaining===1?'':'s')+' left'}</strong></div></div><p>${x.action?'This action is logged. Undo to put the food back.':`Projected on ${days[state.day]}: ${cleanQty(projected?.qty||0)} ${f.unit}${projected?.plannedQty>.05?' (includes '+cleanQty(projected.plannedQty)+' planned)':''}. ${f.note}`}</p><button class="button plum full" data-cook="${f.id}" ${x.action||status==='overdue'?'disabled':''}>Plan a meal with this ↗</button><button class="button secondary full" data-action="frozen" data-id="${f.id}" ${x.action||x.place==='freezer'||status==='overdue'?'disabled':''}>Move to freezer ❄</button><div class="action-row"><button data-action="used" data-id="${f.id}" ${x.action?'disabled':''}>I used it ✓</button><button data-edit="${f.id}">Edit stock</button><button data-action="wasted" data-id="${f.id}" ${x.action?'disabled':''}>Log waste</button></div>${previous?'<button class="link-button" id="undo">Undo last food action</button>':''}`;}
function renderMeals(){$('#meals').innerHTML=days.map((day,d)=>{const r=meal(state,d),away=state.away&&d>=5;return `<article class="meal-card"><div class="meal-day">${day.slice(0,3).toUpperCase()}<span>${d===state.day?'●':''}</span></div><img src="assets/${away?'hero':r.image}.jpg" alt="${away?'Fresh produce':r.name+' inspiration'}" loading="lazy"><div class="meal-body"><h3>${away?'Out of the kitchen':r.name}</h3><p>${away?'Away · no meal ingredients':r.time+' · '+(r.veg?'Plant-forward':'Family favourite')}</p>${away?'<span>↗</span>':`<button data-swap="${d}" aria-label="Swap ${day} dinner">Swap dinner ↻</button>`}</div></article>`}).join('');}
function renderShopping(){const p=plan(state);$('#timingCompare').innerHTML=['None','Wednesday','Thursday'].map(top=>{const v=plan(state,{top});return `<button class="timing-option ${state.topDay===top?'active':''}" data-timing="${top}" aria-pressed="${state.topDay===top}"><span>${top==='None'?'One shop':top.slice(0,3)+' top-up'}</span><strong>${money(v.total)}</strong><small>${money(v.fees)} trip costs</small><small>${money(v.atRisk)} needs a freeze plan</small></button>`}).join('');$('#storeCompare').innerHTML=state.stores.map((s,i)=>`<button class="store-option ${i===state.store?'active':''}" data-store="${i}" aria-pressed="${i===state.store}"><span>${s.name}<small>${s.factor}% price level · ${money(s.fee+s.travel)} / trip</small></span><strong>${money(plan(state,{store:i}).total)}</strong></button>`).join('');$('#storeInputs').innerHTML=state.stores.map((s,i)=>`<div class="store-input"><span>${s.name}</span><label>Price %<input type="number" min="50" max="150" data-store-input="${i}" data-field="factor" value="${s.factor}" aria-label="${s.name} price percentage"></label><label>Shop fee<input type="number" min="0" max="100" data-store-input="${i}" data-field="fee" value="${s.fee}" aria-label="${s.name} shop fee"></label><label>Travel $<input type="number" min="0" max="100" data-store-input="${i}" data-field="travel" value="${s.travel}" aria-label="${s.name} travel cost"></label></div>`).join('');$('#shops').innerHTML=p.shops.map(s=>`<article class="shop-card"><div class="shop-head"><div><small>${s.kind==='main'?'THE MAIN SHOP':'THE FRESH TOP-UP'}</small><h3>${s.day}</h3></div><strong>${money(s.items.reduce((n,x)=>n+x.cost,0))}</strong></div><div class="shop-items">${s.items.length?s.items.map(x=>{const f=foods.find(f=>f.id===x.id),id=s.kind+'-'+x.id,done=state.checked.includes(id);return `<div class="shop-item ${done?'done':''}"><label><input type="checkbox" data-check="${id}" ${done?'checked':''}>${f.name}</label><small>${cleanQty(x.qty)} ${f.unit}</small><span>${money(x.cost)}</span></div>`}).join(''):'<p class="small-copy">Already covered by your kitchen.</p>'}</div></article>`).join('');$('#prices').innerHTML=foods.map(f=>`<label>${f.name} / ${f.unit}<input type="number" min="0" max="200" step="0.1" data-price="${f.id}" value="${unitPrice(state,f.id)}" aria-label="${f.name} unit price"></label>`).join('');}
function selectFood(id,scroll=false){selected=id;scene?.setSelected(id);renderInspector();renderInventory();if(scroll)$('#inspector').scrollIntoView({behavior:reduce?'instant':'smooth',block:'nearest'});}
function openInventory(id){const x=state.inventory.find(x=>x.id===id),f=foods.find(f=>f.id===id)||foods[0];$('#foodSelect').value=f.id;$('#qty').value=x?.qty||1;$('#due').value=x?.due??3;$('#place').value=x?.place||f.place;$('#qtyUnit').textContent='('+f.unit+')';$('#inventoryDialog').showModal();}
function cookWith(id){const stock=state.inventory.find(x=>x.id===id);if(!stock||stockStatus(stock,state.day)==='overdue')return;const d=state.day;if(state.away&&d>=5){toast('You are away this weekend. Choose a weekday or turn off weekend away.');return;}const choices=recipes.map((r,i)=>({r,i})).filter(x=>x.r.ingredients[id]&&(state.diet!=='vegetarian'||x.r.veg));if(!choices.length){toast('Use this for breakfast or a snack; no matching dinner in this recipe set.');return;}checkpoint();state.meals[d]=choices[0].i;state.checked=[];update();toast(days[d]+': '+choices[0].r.name+'. Your shop has been recalculated.');}
function logAction(id,action){const x=state.inventory.find(x=>x.id===id);if(!x||x.action)return;if(action==='frozen'&&(stockStatus(x,state.day)==='overdue'||x.place==='freezer'))return;checkpoint();if(action==='frozen')x.place='freezer';else x.action=action;state.events.push({id,action,qty:x.qty,day:state.day});state.checked=[];update();toast(action==='frozen'?'Moved to the freezer. Check safe freezing and thawing instructions.':action==='used'?'Use recorded. Your remaining stock and shopping list are updated.':'Waste recorded. Useful information for the next plan.');}
function handoffData(){return {type:'assembl.shopping_list',version:3,createdAt:new Date().toISOString(),mode:'planning',priceStatus:'illustrative',household:{adults:state.adults,children:state.kidsHome?state.kids:0,awayWeekend:state.away,lunchboxes:state.lunch},timing:'Relative Monday-Sunday week; main shop is preceding weekend unless Monday',retailerPreference:state.retailer,connectionStatus:'not_connected',shops:plan(state).shops.map(s=>({day:s.day,kind:s.kind,items:s.items.map(x=>({name:foods.find(f=>f.id===x.id).name,quantity:x.qty,unit:foods.find(f=>f.id===x.id).unit,estimatedUnitPriceNZD:x.price,estimatedLineTotalNZD:+x.cost.toFixed(2)}))})),estimatedTripCostsNZD:plan(state).fees,notes:['Review dates, product matches, quantities, dietary requirements and current prices.','Price level profiles are user assumptions, not retailer quotes.','Oil, seasoning and optional flavourings are extra.','No account is connected. Explicit approval required before checkout.']};}
const listText=()=>handoffData().shops.map(s=>s.day+' — '+s.kind+' shop\n'+s.items.map(f=>`[ ] ${f.name}: ${cleanQty(f.quantity)} ${f.unit} — ${money(f.estimatedLineTotalNZD)} est.`).join('\n')).join('\n\n')+'\n\nExample NZD prices. Review product matches and current prices. No order placed. Oil/seasonings extra.';
async function copyList(){try{await navigator.clipboard.writeText(listText());toast('Your shopping list is copied.');}catch{downloadFile('kitchen-shopping-list.txt',listText(),'text/plain');toast('Clipboard unavailable. A text list was downloaded.');}}
function downloadFile(name,body,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function setScanMatches(){const ids=findFood($('#scanText').value);$('#scanMatches').innerHTML=ids.length?ids.map(id=>`<label class="scan-match"><input type="checkbox" data-match="${id}" checked>${foods.find(f=>f.id===id).name}</label>`).join(''):'<p class="small-copy">No matches yet. Try a food such as milk, carrots or spinach. You can add other items from the food selector.</p>';$('#addMatches').disabled=ids.length===0;}
async function readText(){if(ocrBusy||!scanURL)return;ocrBusy=true;$('#readImage').disabled=true;$('#scanFile').disabled=true;$('#scanStatus').textContent='Loading the on-device text reader…';let worker;try{if(!window.Tesseract)await new Promise((res,rej)=>{const s=document.createElement('script');s.src='vendor/tesseract.min.js';s.onload=res;s.onerror=rej;document.head.append(s)});worker=await window.Tesseract.createWorker('eng',1,{workerPath:new URL('vendor/worker.min.js',location.href).href,logger:m=>{$('#scanStatus').textContent=m.status==='recognizing text'?'Reading text: '+Math.round(m.progress*100)+'%':'Preparing the local text reader…';}});const result=await worker.recognize(scanURL);$('#scanText').value=result.data.text.slice(0,10000);setScanMatches();$('#scanStatus').textContent='Text read. Correct the text and check every food before adding.';}catch(e){$('#scanStatus').textContent='The text reader could not load. Paste the list or add foods manually; your image has not been uploaded.';}finally{if(worker)await worker.terminate();ocrBusy=false;$('#readImage').disabled=false;$('#scanFile').disabled=false;}}
$('#foodSelect').innerHTML=foods.map(f=>`<option value="${f.id}">${f.name}</option>`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open){if(b.dataset.open==='inventoryDialog')openInventory();else $('#'+b.dataset.open).showModal();}if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.count){state[b.dataset.count]=Math.max(b.dataset.count==='adults'?1:0,Math.min(8,state[b.dataset.count]+Number(b.dataset.delta)));state.checked=[];update();}if(b.dataset.select)selectFood(b.dataset.select,true);if(b.dataset.action)logAction(b.dataset.id,b.dataset.action);if(b.dataset.edit)openInventory(b.dataset.edit);if(b.dataset.cook)cookWith(b.dataset.cook);if(b.dataset.filter){filter=b.dataset.filter;$$('[data-filter]').forEach(v=>{v.classList.toggle('active',v===b);v.setAttribute('aria-pressed',v===b)});renderInventory();}if(b.dataset.view){scene?.setView(b.dataset.view==='kitchen'?'overview':b.dataset.view);$$('[data-view]').forEach(v=>v.classList.toggle('active',v===b));}if(b.dataset.swap!==undefined){const d=Number(b.dataset.swap);let n=(state.meals[d]+1)%recipes.length;while(state.diet==='vegetarian'&&!recipes[n].veg)n=(n+1)%recipes.length;state.meals[d]=n;state.checked=[];update();toast('Dinner swapped. The list follows your plan.');}if(b.dataset.timing){state.topDay=b.dataset.timing;state.checked=[];update();}if(b.dataset.store!==undefined){state.store=Number(b.dataset.store);update();}if(b.id==='undo'&&previous){state=previous;previous=null;update();toast('Last food action undone.');}});
$('#kidsToggle').onclick=e=>{const b=e.target.closest('button');if(!b)return;state.kidsHome=b.dataset.value==='true';state.checked=[];update();};for(const id of ['away','lunch','includePlanned'])$('#'+id).onchange=e=>{state[id]=e.target.checked;state.checked=[];update();};for(const id of ['diet','mainDay','topDay','retailer'])$('#'+id).onchange=e=>{state[id]=e.target.value;state.checked=[];update();};$('#budget').oninput=e=>{state.budget=Number(e.target.value);renderControls();save();};$('#day').oninput=e=>{stopPlay();state.day=Number(e.target.value);update();};function stopPlay(){clearInterval(playing);playing=null;$('#playWeek').textContent='▶';$('#playWeek').setAttribute('aria-label','Play the simulated week');}$('#playWeek').onclick=()=>{if(playing){stopPlay();return;}if(state.day===6)state.day=0;$('#playWeek').textContent='Ⅱ';$('#playWeek').setAttribute('aria-label','Pause the simulated week');update();playing=setInterval(()=>{if(state.day===6){stopPlay();return;}state.day++;update();},2000);};$('#doorButton').onclick=()=>{door=!door;scene?.setDoor(door);$('#doorButton').textContent=door?'Close fridge':'Open fridge';$('#doorButton').setAttribute('aria-pressed',door);};$('#resetView').onclick=()=>scene?.setView('overview');$('#expandKitchen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#simulator').requestFullscreen();}catch{toast('Fullscreen is unavailable here. Use Fridge view and the zoom controls.');}};document.addEventListener('fullscreenchange',()=>{$('#expandKitchen').textContent=document.fullscreenElement?'Exit kitchen ⤡':'Enter kitchen ⤢';scene?.resize();});$('#zoomIn').onclick=()=>scene?.zoom(1);$('#zoomOut').onclick=()=>scene?.zoom(-1);$('#missionAction').onclick=e=>{if(e.currentTarget.dataset.target)selectFood(e.currentTarget.dataset.target,true);};$('#tour').onclick=()=>{$('#simulator').scrollIntoView({behavior:reduce?'instant':'smooth'});toast('1. Tap food. 2. Change who is home. 3. Slide the week forward.');};$('#reset').onclick=()=>{stopPlay();state=defaults();selected='spinach';previous=null;filter='all';update();toast('Example kitchen reset.');};$('#clearStock').onclick=()=>{checkpoint();state.inventory=[];state.events=[];state.sample=false;state.checked=[];selected=null;update();toast('Your kitchen is empty. Add what you actually have.');};$('#erase').onclick=()=>{stopPlay();state=defaults();state.inventory=[];state.events=[];state.sample=false;state.checked=[];selected=null;previous=null;update();localStorage.removeItem(key);$('#savedStatus').textContent='Saved data cleared';toast('Saved settings and kitchen data cleared.');};$('#inventoryForm').onsubmit=e=>{e.preventDefault();const id=$('#foodSelect').value;checkpoint();const item={id,qty:Number($('#qty').value),due:Number($('#due').value),place:$('#place').value,action:null};const i=state.inventory.findIndex(x=>x.id===id);if(i>=0)state.inventory[i]=item;else state.inventory.push(item);state=sanitise(state);selected=id;state.checked=[];$('#inventoryDialog').close();update();toast('Kitchen updated. Your shopping list is recalculated.');};$('#foodSelect').onchange=e=>{const f=foods.find(f=>f.id===e.target.value);$('#qtyUnit').textContent='('+f.unit+')';$('#place').value=f.place;$('#due').value=horizon[f.id];};document.addEventListener('change',e=>{const t=e.target;if(t.dataset.check){state.checked=t.checked?[...new Set([...state.checked,t.dataset.check])]:state.checked.filter(x=>x!==t.dataset.check);save();renderShopping();}if(t.dataset.price){const n=Number(t.value);if(t.value!==''&&Number.isFinite(n)&&n>=0&&n<=200){state.prices[t.dataset.price]=n;update();}else{t.value=unitPrice(state,t.dataset.price);toast('Enter a price from $0 to $200.');}}if(t.dataset.storeInput!==undefined){const i=Number(t.dataset.storeInput),k=t.dataset.field,n=Number(t.value),min=k==='factor'?50:0,max=k==='factor'?150:100;if(t.value!==''&&Number.isFinite(n)&&n>=min&&n<=max){state.stores[i][k]=n;update();}else{t.value=state.stores[i][k];toast('Enter a value between '+min+' and '+max+'.');}}if(t.dataset.match)$('#addMatches').disabled=!$$('[data-match]:checked').length;});$('#rescuePlan').onclick=()=>{checkpoint();const urgent=state.inventory.filter(x=>!x.action&&x.place!=='freezer'&&x.due>=state.day).sort((a,b)=>a.due-b.due);const used=new Set();for(let d=state.day;d<7;d++){if(state.away&&d>=5)continue;const ranked=recipes.map((r,i)=>({i,r,score:urgent.reduce((n,x)=>n+(r.ingredients[x.id]&&x.due>=d?x.qty/(x.due-state.day+1):0),0)})).filter(x=>(state.diet!=='vegetarian'||x.r.veg)&&!used.has(x.i)).sort((a,b)=>b.score-a.score);if(ranked[0]?.score>0){state.meals[d]=ranked[0].i;used.add(ranked[0].i);}}state.checked=[];update();toast('Meals reordered around usable stock and its planning dates.');};$('#copy').onclick=copyList;$('#copyHandoff').onclick=copyList;$('#export').onclick=()=>{downloadFile('kitchen-plan.json',JSON.stringify(handoffData(),null,2),'application/json');toast('Reviewed plan exported as JSON.');};$('#reviewHandoff').onclick=()=>{const links={newworld:'https://www.newworld.co.nz/',woolworths:'https://www.woolworths.co.nz/',paknsave:'https://www.paknsave.co.nz/'};const p=plan(state);$('#handoffSummary').textContent=p.shops.reduce((n,s)=>n+s.items.length,0)+' shopping lines across '+p.shops.length+' planned shops. '+money(p.total)+' including your estimated trip costs.';$('#openRetailer').href=links[state.retailer];$('#handoffDialog').showModal();};$('#share').onclick=async()=>{try{await navigator.clipboard.writeText('https://kitchen-machine-kate.katecoveny.chatgpt.site/retailer-demo.html');toast('Retailer demo link copied. It starts with sample data; your kitchen data is not shared.');}catch{toast('Share this site’s address. Your personal kitchen data stays on this device.');}};
$('#scanFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){toast('Choose a JPG, PNG or WebP image under 10 MB.');e.target.value='';return;}if(scanURL)URL.revokeObjectURL(scanURL);scanURL=URL.createObjectURL(f);$('#scanPreview').src=scanURL;$('#scanPreview').hidden=false;$('#readImage').disabled=false;$('#scanStatus').textContent='Photo stays on this device. Read written text, or manually name the foods you can see.';};$('#readImage').onclick=readText;$('#matchText').onclick=setScanMatches;$('#sampleScan').onclick=()=>{$('#scanText').value='Milk 2L\nSpinach\nCarrots\nApples\nBread';setScanMatches();$('#scanStatus').textContent='Example list loaded. Review quantities after adding.';};$('#addMatches').onclick=()=>{checkpoint();for(const input of $$('[data-match]:checked')){const id=input.dataset.match;if(!state.inventory.some(x=>x.id===id&&!x.action)){state.inventory=state.inventory.filter(x=>x.id!==id);state.inventory.push({id,qty:1,due:horizon[id],place:foods.find(f=>f.id===id).place,action:null});}}state.checked=[];update();$('#scanDialog').close();toast('Reviewed foods added. Existing stock kept; edit quantities and dates in your kitchen.');};
